//! NFX-16 seeder ratings against their vectors (`spec/test-vectors/ratings*.json`,
//! generated by `ratings.py`), natively and on `wasm32`. The Rust reader must classify
//! every vector as the reference reader does, and reproduce every signed event byte for
//! byte from the published throwaway keys.

#![allow(clippy::unwrap_used, clippy::expect_used)]

#[cfg(target_arch = "wasm32")]
use wasm_bindgen_test::wasm_bindgen_test as test;

use nfx_proto::KIND_RATING;
use nfx_proto::event::{Event, public_key_hex};
use nfx_proto::rating::{
    Admitted, KIND_FOLLOWS, KIND_MUTES, MAX_FOLLOWS, Rating, Score, Verdict, listed_pubkeys, score,
};
use serde_json::Value;

macro_rules! vector {
    ($name:literal) => {
        serde_json::from_str::<Value>(include_str!(concat!("../../../spec/test-vectors/", $name)))
            .expect(concat!("vector ", $name, " is JSON"))
    };
}

fn event(v: &Value) -> Event {
    serde_json::from_value(v.clone()).unwrap()
}

fn secret(v: &Value, who: &str) -> [u8; 32] {
    let hex = v["secret_keys_DO_NOT_USE"][who].as_str().unwrap();
    let mut out = [0u8; 32];
    hex::decode_to_slice(hex, &mut out).unwrap();
    out
}

fn resign(original: &Event, secret: &[u8; 32]) -> Event {
    Event::sign(
        secret,
        original.created_at,
        original.kind,
        original.tags.clone(),
        original.content.clone(),
    )
    .unwrap()
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v[key]
        .as_str()
        .unwrap_or_else(|| panic!("{key} is a string"))
}

fn strs(v: &Value) -> Vec<&str> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap())
        .collect()
}

#[test]
fn valid_ratings_read_as_published_and_are_reproduced() {
    let v = vector!("ratings.json");
    let ns = str_of(&v, "namespace");
    let watcher = secret(&v, "watcher");
    let cases = v["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 3);
    for case in cases {
        let name = str_of(case, "name");
        let ev = event(&case["event"]);
        assert_eq!(ev.kind, KIND_RATING, "{name}");
        assert_eq!(resign(&ev, &watcher), ev, "{name} is reproduced");
        let r = Rating::from_event(&ev, ns).unwrap_or_else(|e| panic!("{name}: {e}"));
        let want = &case["reads_as"];
        assert_eq!(r.rater, str_of(want, "rater"), "{name}");
        assert_eq!(r.subject, str_of(want, "subject"), "{name}");
        assert_eq!(r.rating, want["rating"].as_i64().unwrap(), "{name}");
        assert_eq!(r.created_at, want["created_at"].as_u64().unwrap(), "{name}");
        assert_eq!(r.expiration, want["expiration"].as_u64().unwrap(), "{name}");
        assert_eq!(r.id, ev.id, "{name}");
        assert_eq!(r.event_created_at, ev.created_at, "{name}");
        // Another network's reader rejects it.
        assert!(Rating::from_event(&ev, "nfx:testnet:1").is_err(), "{name}");
    }
}

#[test]
fn invalid_ratings_are_all_rejected() {
    let v = vector!("ratings-invalid.json");
    let ns = str_of(&v, "namespace");
    let watcher = secret(&v, "watcher");
    let cases = v["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 23);
    for case in cases {
        let name = str_of(case, "name");
        let ev = event(&case["event"]);
        assert!(
            Rating::from_event(&ev, ns).is_err(),
            "{name} must be rejected"
        );
        // Each case is rejected for its own defect, not a broken signature, except the
        // two cases that are about the signature.
        if !matches!(name, "id-mismatch" | "bad-sig") {
            ev.verify()
                .unwrap_or_else(|e| panic!("{name} verifies: {e}"));
            assert_eq!(resign(&ev, &watcher), ev, "{name} is reproduced");
        } else {
            assert!(ev.verify().is_err(), "{name}");
        }
    }
}

fn verdict_of(text: &str) -> Verdict {
    match text {
        "counted" => Verdict::Counted,
        "newest, a withdrawal: adds nothing" => Verdict::Withdrawal,
        "ignored: author not admitted" => Verdict::NotAdmitted,
        "ignored: from the future" => Verdict::FromFuture,
        "ignored: expired" => Verdict::Expired,
        t if t.starts_with("superseded") => Verdict::Superseded,
        t => {
            let reason = t
                .strip_prefix("ignored: invalid (")
                .and_then(|r| r.strip_suffix(')'))
                .unwrap_or_else(|| panic!("unknown verdict {t:?}"));
            Verdict::Invalid(reason.to_string())
        }
    }
}

#[test]
fn scoring_matches_the_reference_reader() {
    let v = vector!("ratings-scoring.json");
    let ns = str_of(&v, "namespace");
    let now = v["now"].as_u64().unwrap();
    let follows = strs(&v["follows"]);
    let trusted = strs(&v["trusted"]);
    let muted = strs(&v["muted"]);
    let admitted = Admitted::new(
        str_of(&v, "root"),
        follows.iter().copied(),
        trusted.iter().copied(),
        muted.iter().copied(),
    );

    // Every event is reproduced from its author's published key.
    let by_pubkey: std::collections::BTreeMap<&str, &str> = v["pubkeys"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(name, pk)| (pk.as_str().unwrap(), name.as_str()))
        .collect();
    let entries = v["events"].as_array().unwrap();
    assert_eq!(entries.len(), 15);
    let events: Vec<Event> = entries.iter().map(|e| event(&e["event"])).collect();
    for (entry, ev) in entries.iter().zip(&events) {
        let who = by_pubkey[ev.pubkey.as_str()];
        let sk = secret(&v, who);
        assert_eq!(public_key_hex(&sk).unwrap(), ev.pubkey);
        assert_eq!(
            resign(ev, &sk),
            *ev,
            "{} is reproduced",
            str_of(entry, "name")
        );
    }

    let scored = score(&events, ns, now, &admitted);
    for (entry, got) in entries.iter().zip(&scored.verdicts) {
        assert_eq!(
            *got,
            verdict_of(str_of(entry, "verdict")),
            "{}",
            str_of(entry, "name")
        );
    }
    let want: std::collections::BTreeMap<String, Score> = v["scores"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(subject, s)| {
            (
                subject.clone(),
                Score {
                    score: s["score"].as_i64().unwrap(),
                    authors: s["authors"].as_u64().unwrap(),
                },
            )
        })
        .collect();
    assert_eq!(scored.scores, want);

    // The order of the events does not change the scores.
    let mut reversed = events.clone();
    reversed.reverse();
    assert_eq!(score(&reversed, ns, now, &admitted).scores, want);

    // Nobody admitted, nothing counted.
    let none = std::iter::empty::<&str>;
    let nobody = Admitted::new(&"0".repeat(64), none(), none(), none());
    assert!(score(&events, ns, now, &nobody).scores.is_empty());
}

#[test]
fn mutes_win_over_follows_trust_and_the_root() {
    let a = Admitted::new("root", ["f1", "f2"], ["t1"], ["f2", "root"]);
    assert_eq!(a.authors().collect::<Vec<_>>(), ["f1", "t1"]);
    assert!(!a.contains("root"));
    assert_eq!(a.len(), 2);
}

#[test]
fn lists_read_p_tags_only_from_their_author() {
    let sk = [7u8; 32];
    let me = public_key_hex(&sk).unwrap();
    let x = "a".repeat(64);
    let y = "b".repeat(64);
    let tags = vec![
        vec!["p".into(), x.clone()],
        vec!["p".into(), "B".repeat(64)],
        vec!["p".into(), x.clone(), "wss://relay.example".into()],
        vec!["e".into(), y.clone()],
        vec!["p".into(), y.clone()],
        vec!["p".into()],
        vec![],
    ];
    let ev = Event::sign(&sk, 1, KIND_FOLLOWS, tags, String::new()).unwrap();
    assert_eq!(listed_pubkeys(&ev, KIND_FOLLOWS, &me).unwrap(), [x, y]);
    assert!(listed_pubkeys(&ev, KIND_MUTES, &me).is_err());
    assert!(listed_pubkeys(&ev, KIND_FOLLOWS, &"c".repeat(64)).is_err());
    assert!(listed_pubkeys(&ev, KIND_RATING, &me).is_err());
    let mut forged = ev;
    forged.tags.pop();
    assert!(listed_pubkeys(&forged, KIND_FOLLOWS, &me).is_err());
}

#[test]
fn follow_lists_are_capped_and_mute_lists_are_not() {
    let sk = [9u8; 32];
    let me = public_key_hex(&sk).unwrap();
    let tags: Vec<Vec<String>> = (0..=MAX_FOLLOWS)
        .map(|i| vec!["p".into(), format!("{i:064x}")])
        .collect();
    let follows = Event::sign(&sk, 1, KIND_FOLLOWS, tags.clone(), String::new()).unwrap();
    assert_eq!(
        listed_pubkeys(&follows, KIND_FOLLOWS, &me).unwrap().len(),
        MAX_FOLLOWS
    );
    let mutes = Event::sign(&sk, 1, KIND_MUTES, tags, String::new()).unwrap();
    assert_eq!(
        listed_pubkeys(&mutes, KIND_MUTES, &me).unwrap().len(),
        MAX_FOLLOWS + 1
    );
}
